"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1438],{55437:e=>{e.exports=JSON.parse('{"functions":[{"name":"ReportProgress","desc":"Report an actor-driven metric (e.g. junk the actor collected). Credits the\\nactor\'s Personal quests and fans the same amount out to every player\'s Party\\nquests. The raw lifetime metric total is credited to the actor only.","params":[{"name":"actor","desc":"","lua_type":"Player"},{"name":"metricKey","desc":"","lua_type":"string"},{"name":"amount","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":191,"path":"src/ServerStorage/SharedModules/QuestManager.luau"}},{"name":"ReportPartyProgress","desc":"Report an ownerless world metric (e.g. an enemy died, train distance ticked).\\nAdvances every player\'s Party quests and credits each their lifetime metric\\ntotal. Personal quests are untouched (no single actor).","params":[{"name":"metricKey","desc":"","lua_type":"string"},{"name":"amount","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":216,"path":"src/ServerStorage/SharedModules/QuestManager.luau"}},{"name":"ClaimQuest","desc":"Claim a completed quest\'s reward. Idempotent: the claimed flag is set BEFORE\\nthe grant, so a re-entrant call cannot double-pay. Returns\\n(ok, reasonCode, coinsGranted, expGranted); amounts are 0 on any failure.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"questId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"number"},{"desc":"","lua_type":"number"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":236,"path":"src/ServerStorage/SharedModules/QuestManager.luau"}},{"name":"GetLifetimeStat","desc":"Read a persisted lifetime stat (e.g. \\"QuestsCompleted\\", \\"metric:EnemyKills\\").\\nThe perk seam: a future PerkConfig criterion reads this. Returns 0 if absent.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"key","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":273,"path":"src/ServerStorage/SharedModules/QuestManager.luau"}},{"name":"Initialize","desc":"Wire up the profile lifecycle, the claim handler, and the live rollover tick.\\nCall exactly once per server (from a loader). Safe in both places.","params":[],"returns":[],"function_type":"static","source":{"line":312,"path":"src/ServerStorage/SharedModules/QuestManager.luau"}}],"properties":[],"types":[],"name":"QuestManager","desc":"Place-agnostic authority for daily/weekly quests. Owns the PlayerQuests\\nProfileStore profile (one session per player, key = UserId), rotation/rollover,\\nprogress, claim, lifetime stats, and per-player replication via QuestStateSync.\\n\\nRuns in BOTH the lobby and gameplay places (lobby needs display + claim). The\\nprogress SOURCES (kills, distance, junk) live in the gameplay-only\\nQuestSourcesLoader, not here \u2014 mirroring XPManager / XPSystemLoader.\\n\\nCross-place: STORE_NAME + tostring(UserId) key are identical in every place, so\\nthe same DataStore record is shared; ProfileStore session-locking serialises the\\nlobby\u2194gameplay handoff. The active quest SET is never stored \u2014 QuestState\\nrecomputes it deterministically from the period index.","realm":["Server"],"source":{"line":19,"path":"src/ServerStorage/SharedModules/QuestManager.luau"}}')}}]);